#include <iostream>
#include <vector>
#include <cuda_runtime.h>
#include <mpi.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <stdexcept>

// CUDA kernel for neuron integration
__global__ void integrate_neurons_kernel(float* v, float* u, const float* a, const float* b, 
                                        const float* threshold, const float* c, const float* d,
                                        const float* input, float dt, int num_neurons) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_neurons) {
        // Izhikevich neuron dynamics
        float dv = (0.04f * v[i] * v[i] + 5.0f * v[i] + 140.0f - u[i] + input[i]) * dt;
        v[i] += dv;

        float du = (a[i] * (b[i] * v[i] - u[i])) * dt;
        u[i] += du;
    }
}

// CUDA kernel for spike detection and reset
__global__ void detect_spikes_kernel(float* v, float* u, const float* threshold, 
                                    const float* c, const float* d, float* last_spike_time,
                                    bool* spike, float current_time, int num_neurons) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_neurons) {
        if (v[i] >= threshold[i]) {
            spike[i] = true;
            last_spike_time[i] = current_time;
            v[i] = c[i];
            u[i] += d[i];
        } else {
            spike[i] = false;
        }
    }
}

// CUDA kernel for STDP updates
__global__ void update_stdp_kernel(const bool* spike, const float* last_spike_time,
                                 float* weights, int* row_indices, int* col_indices,
                                 int num_connections, float tau_stdp, float min_weight, float max_weight) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < num_connections) {
        int pre_idx = row_indices[i];
        int post_idx = col_indices[i];

        float delta_t = last_spike_time[post_idx] - last_spike_time[pre_idx];

        // Pre-post pairing (LTP)
        if (delta_t > 0 && delta_t < tau_stdp) {
            float w_new = fminf(max_weight, weights[i] + 0.1f * (1.0f - weights[i]));
            weights[i] = w_new;
        } 
        // Post-pre pairing (LTD)
        else if (delta_t < 0 && -delta_t < tau_stdp) {
            float w_new = fmaxf(min_weight, weights[i] - 0.1f * weights[i]);
            weights[i] = w_new;
        }
    }
}

class DistributedNeuralNetwork {
public:
    DistributedNeuralNetwork(int total_neurons, int local_neurons, float dt)
        : total_neurons_(total_neurons), local_neurons_(local_neurons), dt_(dt) {

        // Initialize MPI
        MPI_Comm_size(MPI_COMM_WORLD, &num_procs_);
        MPI_Comm_rank(MPI_COMM_WORLD, &rank_);

        // Allocate device memory for neuron states
        checkCudaErrors(cudaMalloc(&v_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&u_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&a_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&b_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&c_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&d_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&threshold_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&last_spike_time_, local_neurons_ * sizeof(float)));
        checkCudaErrors(cudaMalloc(&spike_, local_neurons_ * sizeof(bool)));

        // Initialize neuron parameters (default values)
        std::vector<float> h_a(local_neurons_, 0.02f);
        std::vector<float> h_b(local_neurons_, 0.2f);
        std::vector<float> h_c(local_neurons_, -65.0f);
        std::vector<float> h_d(local_neurons_, 8.0f);
        std::vector<float> h_threshold(local_neurons_, 30.0f);

        checkCudaErrors(cudaMemcpy(a_, h_a.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(b_, h_b.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(c_, h_c.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(d_, h_d.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(threshold_, h_threshold.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));

        // Initialize membrane potential and recovery variable
        std::vector<float> h_v(local_neurons_, -70.0f);
        std::vector<float> h_u(local_neurons_, 0.0f);
        std::vector<float> h_last_spike_time(local_neurons_, -1.0f);

        checkCudaErrors(cudaMemcpy(v_, h_v.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(u_, h_u.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(last_spike_time_, h_last_spike_time.data(), local_neurons_ * sizeof(float), cudaMemcpyHostToDevice));
    }

    ~DistributedNeuralNetwork() {
        // Free device memory
        checkCudaErrors(cudaFree(v_));
        checkCudaErrors(cudaFree(u_));
        checkCudaErrors(cudaFree(a_));
        checkCudaErrors(cudaFree(b_));
        checkCudaErrors(cudaFree(c_));
        checkCudaErrors(cudaFree(d_));
        checkCudaErrors(cudaFree(threshold_));
        checkCudaErrors(cudaFree(last_spike_time_));
        checkCudaErrors(cudaFree(spike_));

        if (row_indices_) checkCudaErrors(cudaFree(row_indices_));
        if (col_indices_) checkCudaErrors(cudaFree(col_indices_));
        if (weights_) checkCudaErrors(cudaFree(weights_));
    }

    void set_connectivity(int* row_indices, int* col_indices, float* weights, int num_connections) {
        // Store synaptic connections in CSR format on device
        num_connections_ = num_connections;

        checkCudaErrors(cudaMalloc(&row_indices_, num_connections * sizeof(int)));
        checkCudaErrors(cudaMalloc(&col_indices_, num_connections * sizeof(int)));
        checkCudaErrors(cudaMalloc(&weights_, num_connections * sizeof(float)));

        checkCudaErrors(cudaMemcpy(row_indices_, row_indices, num_connections * sizeof(int), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(col_indices_, col_indices, num_connections * sizeof(int), cudaMemcpyHostToDevice));
        checkCudaErrors(cudaMemcpy(weights_, weights, num_connections * sizeof(float), cudaMemcpyHostToDevice));
    }

    void step(const std::vector<float>& external_input) {
        // Validate input size
        if (external_input.size() != static_cast<size_t>(local_neurons_)) {
            throw std::invalid_argument("External input size must match number of local neurons");
        }

        // Copy external input to device
        thrust::device_vector<float> d_input(external_input);

        // Integrate neuron dynamics
        int blockSize = 256;
        int numBlocks = (local_neurons_ + blockSize - 1) / blockSize;

        integrate_neurons_kernel<<<numBlocks, blockSize>>>(
            v_, u_, a_, b_, threshold_, c_, d_, 
            thrust::raw_pointer_cast(d_input.data()), dt_, local_neurons_);
        checkCudaErrors(cudaGetLastError());

        // Detect spikes
        detect_spikes_kernel<<<numBlocks, blockSize>>>(
            v_, u_, threshold_, c_, d_, last_spike_time_, spike_, current_time_, local_neurons_);
        checkCudaErrors(cudaGetLastError());

        // Apply STDP updates
        if (num_connections_ > 0) {
            numBlocks = (num_connections_ + blockSize - 1) / blockSize;
            update_stdp_kernel<<<numBlocks, blockSize>>>(
                thrust::raw_pointer_cast(spike_.get()), last_spike_time_, 
                weights_, row_indices_, col_indices_, num_connections_,
                tau_stdp_, min_weight_, max_weight_);
            checkCudaErrors(cudaGetLastError());
        }

        // Communicate spikes between MPI processes
        communicate_spikes();

        current_time_ += dt_;
    }

    void run_simulation(float duration) {
        int steps = static_cast<int>(duration / dt_);
        std::vector<float> input(local_neurons_, 0.0f);

        for (int i = 0; i < steps; ++i) {
            step(input);

